insert into public.prompt_versions (variant_id, version_label, payload, status, is_current, published_at)
select v.id, 'v5-2-extension', l.payload, 'published'::public.version_status, true, now()
from lot_extension_payloads l
join public.prompts p on p.external_ref = l.ref
join public.prompt_variants v on v.prompt_id = p.id
join public.ai_providers pr on pr.id = v.provider_id and pr.key = l.moteur
where not exists (
  select 1 from public.prompt_versions pv where pv.variant_id = v.id and pv.is_current
);

do $ctrl$
declare
  v_pose integer;
begin
  select count(*) into v_pose
  from lot_extension_payloads l
  join public.prompts p on p.external_ref = l.ref
  join public.prompt_variants v on v.prompt_id = p.id
  join public.ai_providers pr on pr.id = v.provider_id and pr.key = l.moteur
  join public.prompt_versions pv on pv.variant_id = v.id and pv.is_current
  where pv.payload = l.payload;
  if v_pose <> 30 then
    raise exception 'Lot 201 : % payloads courants sur 30.', v_pose;
  end if;
end $ctrl$;

drop table lot_extension_payloads;
